package com.example

import com.example.ExamQuestionHelper.QSpec

internal object GeographyLiveExamWorldRegionsBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun worldRegionalQuestions(): List<QSpec> {
    val t = "ලෝක කලාපීය භූගෝල විද්‍යාව"
    return listOf(
      q(t, "භූමි ප්‍රමාණය හා ජනගහනය යන දෙකින්ම ලෝකයේ විශාලතම මහාද්වීපය කුමක්ද?",
        "ආසියා මහාද්වීපය", "අප්‍රිකා මහාද්වීපය", "යුරෝපා මහාද්වීපය", "උතුරු ඇමෙරිකා මහාද්වීපය",
        "ආසියාව පෘථිවි ගොඩබිමෙන් ~30% ක් පමණ ආවරණය කරන අතර ලෝක ජනගහනයෙන් ~59% ක් එහි වාසය කරති."),
      q(t, "ලෝකයේ සියලුම සාගර අතරින් විශාලතම හා ගැඹුරුතම සාගරය කුමක්ද?",
        "පැසිෆික් සාගරය (Pacific Ocean)", "අත්ලාන්තික් සාගරය", "ඉන්දියානු සාගරය", "ආක්ටික් සාගරය",
        "පැසිෆික් සාගරයේ මරියානා ආගාධයේ (Mariana Trench) Challenger Deep ලෝකයේ ගැඹුරුතම ස්ථානය (මීටර් ~11,000) වේ."),
      q(t, "භූමි ප්‍රමාණයෙන් කුඩාම මහාද්වීපය හෙවත් 'දූපත් මහාද්වීපය' ලෙස හඳුන්වනු ලබන්නේ කුමක්ද?",
        "ඕස්ට්‍රේලියාව (ඕෂනියා කලාපය)", "යුරෝපය", "දකුණු ඇමෙරිකාව", "ඇන්ටාක්ටිකාව",
        "ඕස්ට්‍රේලියාව තනි රටක් මෙන්ම මහාද්වීපයක්ද වන අතර එහි 'අවුට්බැක්' (Outback) නම් ශුෂ්ක අභ්‍යන්තරය ප්‍රසිද්ධය."),
      q(t, "සමකය, කර්කටක නිවර්තනය හා මකර නිවර්තනය යන ප්‍රධාන අක්ෂාංශ රේඛා තුනම හරහා ගමන් කරන එකම මහාද්වීපය කුමක්ද?",
        "අප්‍රිකා මහාද්වීපය", "ආසියාව", "දකුණු ඇමෙරිකාව", "යුරෝපය",
        "මේ නිසා අප්‍රිකාවේ උතුරු හා දකුණු අර්ධගෝල දෙකෙහිම නිවර්තන වනාන්තර, සැවානා, කාන්තාර හා මධ්‍යධරණී දේශගුණයන් සමමිතිකව දැකිය හැකිය."),
      q(t, "ආසියාව හා යුරෝපය අතර ස්වාභාවික භූගෝලීය මායිම සකසන ප්‍රධාන කඳු වැටිය හා ගංගාව කුමක්ද?",
        "යූරල් කඳු වැටිය (Ural Mountains) සහ යූරල් ගංගාව (සහ කොකේසස් කඳු වැටිය)", "ඇල්ප්ස් කඳු වැටිය හා රයින් ගංගාව", "ඇන්ඩීස් කඳු වැටිය හා ඇමසන් ගංගාව", "රොකී කඳු වැටිය හා මිසිසිපි ගංගාව",
        "භූගෝලීයව යුරෝපය හා ආසියාව එකම මහා භූස්කන්ධයක් වන 'යුරේසියාව' (Eurasia) සාදයි."),
      q(t, "ලෝකයේ උසම කඳු වැටිය වන හිමාලය කඳු වැටිය (Himalayas) හා ලොව උසම කඳු මුදුන වන එවරස්ට් (මීටර් 8,848.86) පිහිටා ඇත්තේ කුමන කලාපයේද?",
        "දකුණු ආසියාව හා ටිබෙට් සානුව අතර දේශසීමාවේ (නේපාලය-චීනය)", "දකුණු ඇමෙරිකාවේ පේරු රාජ්‍යයේ", "යුරෝපයේ ස්විට්සර්ලන්තයේ", "නැගෙනහිර අප්‍රිකාවේ",
        "හිමාලය කලාපයේ දියවන ග්ලැසියර 'ආසියාවේ ජල කුළුණ' (Water Tower of Asia) ලෙස ගංගා, ඉන්දු, බ්‍රහ්මපුත්‍ර, යැංසි හා මේකොං ගංගාවලට ජලය සපයයි."),
      q(t, "දකුණු ඇමෙරිකාවේ බටහිර වෙරළ දිගේ විහිදෙන ලෝකයේ දිගම මහාද්වීපික කඳු වැටිය (දිග කි.මී. ~7,000) කුමක්ද?",
        "ඇන්ඩීස් කඳු වැටිය (Andes Mountains)", "ඇපලේචියන් කඳු වැටිය", "ඇට්ලස් කඳු වැටිය", "ඩ්‍රැකන්ස්බර්ග් කඳු වැටිය",
        "ආජන්ටිනාවේ පිහිටි ඇකොන්කගුවා (Aconcagua - මීටර් 6,961) ඇන්ඩීස් කඳු වැටියේ සහ ආසියාවෙන් පිටත ලෝකයේ උසම කඳු මුදුනයි."),
      q(t, "යුරෝපයේ මධ්‍යම ප්‍රදේශයේ ප්‍රංශය, ස්විට්සර්ලන්තය, ඉතාලිය, ඔස්ට්‍රියාව හා ජර්මනිය හරහා විහිදෙන ප්‍රධාන තරුණ නැමි කඳු වැටිය කුමක්ද?",
        "ඇල්ප්ස් කඳු වැටිය (Alps Mountains)", "පිරෙනීස් කඳු වැටිය", "කාපේතියන් කඳු වැටිය", "ස්කැන්ඩිනේවියානු කඳු වැටිය",
        "මොන්ට් බ්ලැන්ක් (Mont Blanc) බටහිර යුරෝපයේ උසම කඳු මුදුන වන අතර ඇල්ප්ස් කඳුකරය ජල විදුලිය හා ශීත සංචාරක ව්‍යාපාරයට ප්‍රසිද්ධය."),
      q(t, "ජල පරිමාවෙන් හා ජල පෝෂක ද්‍රෝණියේ විශාලත්වයෙන් ලෝකයේ විශාලතම ගංගාව කුමක්ද?",
        "ඇමසන් ගංගාව (Amazon River - දකුණු ඇමෙරිකාව)", "නයිල් ගංගාව", "මිසිසිපි ගංගාව", "ඩැනියුබ් ගංගාව",
        "ලෝකයේ සමස්ත ගංගා මිරිදිය ගලා යාමෙන් 20% ක් පමණ ඇමසන් ගංගාව මගින් අත්ලාන්තික් සාගරයට මුදා හරියි."),
      q(t, "දිගින් වැඩිම ගංගාවක් ලෙස ප්‍රසිද්ධ 'නයිල් ගංගාව' (Nile River - කි.මී. ~6,650) උතුරු දෙසට ගලා ගොස් අවසානයේ කුමන මුහුදට වැටේද?",
        "මධ්‍යධරණී මුහුදට (ඊජිප්තුව හරහා)", "රතු මුහුදට", "ඉන්දියානු සාගරයට", "පැසිෆික් සාගරයට",
        "සුදු නයිල් (වික්ටෝරියා විල) සහ නිල් නයිල් (ඉතියෝපියාවේ ටානා විල) සුඩානයේ කාර්ටූම් හිදී එක්වේ."),
      q(t, "යුරෝපයේ රටවල් 10 ක් (ජර්මනිය, ඔස්ට්‍රියාව, හංගේරියාව, සර්බියාව, රුමේනියාව ආදී) හරහා හෝ මායිම් ඔස්සේ ගලා ගොස් කළු මුහුදට වැටෙන ජාත්‍යන්තර ගංගාව කුමක්ද?",
        "ඩැනියුබ් ගංගාව (Danube River)", "තේම්ස් ගංගාව", "වොල්ගා ගංගාව", "පෝ ගංගාව",
        "එය ලෝකයේ වැඩිම රටවල් ගණනක් හරහා ගලන ජාත්‍යන්තර ගංගාව වන අතර වියානා, බ්‍රැටිස්ලාවා, බුඩාපෙස්ට් හා බෙල්ග්‍රේඩ් අගනගර එහි ඉවුරේ පිහිටා ඇත."),
      q(t, "ආසියාවේ දිගම ගංගාව වන 'යැංසි ගංගාව' (Yangtze / Chang Jiang) සම්පූර්ණයෙන්ම ගලා යන්නේ කුමන රට තුළද?",
        "චීනය", "ඉන්දියාව", "වියට්නාමය", "ජපානය",
        "ටිබෙට් සානුවෙන් ආරම්භ වන යැංසි ගංගාව මත ලොව විශාලතම ජල විදුලි ව්‍යාපෘතිය වන 'ත්‍රී ගෝජස් වේල්ල' (Three Gorges Dam) ඉදිකර නැගෙනහිර චීන මුහුදට වැටේ."),
      q(t, "භූගෝලීය වශයෙන් 'විලක්' ලෙස නම් කළද විශාලත්වය නිසා මුහුදක් ලෙස හඳුන්වන ලොව විශාලතම අභ්‍යන්තර ජලාශය (Endorheic Lake) කුමක්ද?",
        "කැස්පියන් මුහුද (Caspian Sea)", "සුපීරියර් විල", "බයිකල් විල", "වික්ටෝරියා විල",
        "රුසියාව, කසකස්තානය, තුර්ක්මෙනිස්තානය, ඉරානය හා අසර්බයිජානය යන රටවල් පහකින් වට වූ කැස්පියන් මුහුද තෙල් හා ස්වාභාවික වායුවලින් පොහොසත්ය."),
      q(t, "ජල පරිමාවෙන් හා ගැඹුරෙන් ලෝකයේ ගැඹුරුතම මිරිදිය විල (ගැඹුර මීටර් ~1,642) වන 'බයිකල් විල' (Lake Baikal) පිහිටා ඇත්තේ කොතැනද?",
        "රුසියාවේ දකුණු සයිබීරියාවේ", "කැනඩාවේ", "ටැන්සානියාවේ", "චිලී රාජ්‍යයේ",
        "ලෝකයේ ගලා නොයන මතුපිට මිරිදිය සංචිතයෙන් 20% කට වඩා රැඳී ඇති බයිකල් විල අද්විතීය විවර පැලුම් විලකි."),
      q(t, "ලෝකයේ විශාලතම උණුසුම් කාන්තාරය වන 'සහරා කාන්තාරය' (Sahara Desert) පිහිටා ඇත්තේ කුමන කලාපයේද?",
        "උතුරු අප්‍රිකාවේ (අත්ලාන්තික් වෙරළේ සිට රතු මුහුද දක්වා)", "දකුණු අප්‍රිකාවේ", "මධ්‍යම ආසියාවේ", "දකුණු ඇමෙරිකාවේ",
        "සහරාව රටවල් 11 ක පමණ විහිදෙන අතර ඇමෙරිකා එක්සත් ජනපදයේ විශාලත්වයට ආසන්න භූමි ප්‍රමාණයක් ගනී."),
      q(t, "පෘථිවියේ වියළිම ධ්‍රැවීය නොවන කාන්තාරය (Hyper-arid Desert) වන 'ඇටකාමා කාන්තාරය' (Atacama Desert) පිහිටා ඇත්තේ කුමන රටකද?",
        "උතුරු චිලී රාජ්‍යයේ (දකුණු ඇමෙරිකාව)", "මොරොක්කෝවේ", "මොංගෝලියාවේ", "ඕමානයේ",
        "හම්බෝල්ට් ශීත සාගර දියවැල හා ඇන්ඩීස් කඳුවැටියේ වැසි සෙවණැලි ආචරණය නිසා එහි ඇතැම් ස්ථානවල දශක ගණනක් වැසි ලැබී නැත."),
      q(t, "ආසියාවේ චීනය සහ මොංගෝලියාව අතර විහිදෙන ප්‍රධාන සෞම්‍ය ශීතල කාන්තාරය කුමක්ද?",
        "ගෝබි කාන්තාරය (Gobi Desert)", "තාර් කාන්තාරය", "රුබ් අල් කාලි කාන්තාරය", "කලහාරි කාන්තාරය",
        "හිමාලය කඳුවැටිය ඉන්දියානු සාගරයේ තෙතමනය අවහිර කිරීම ගෝබි කාන්තාරය ඇතිවීමට ප්‍රධාන හේතුවකි."),
      q(t, "ඉන්දියාවේ වයඹදිග කොටසේ (රාජස්ථාන්) සහ පකිස්තානයේ ගිනිකොනදිග කොටසේ පිහිටි ජනාකීර්ණ කාන්තාරය කුමක්ද?",
        "තාර් කාන්තාරය (Thar Desert / Great Indian Desert)", "නමිබ් කාන්තාරය", "මොජාවේ කාන්තාරය", "සිම්ප්සන් කාන්තාරය",
        "ඉන්දිරා ගාන්ධි ඇළ මාර්ගය ඔස්සේ ජලය සැපයීමෙන් මෙම කාන්තාරයේ කොටස් වගා බිම් බවට පත් කර ඇත."),
      q(t, "මධ්‍යධරණී මුහුද සහ රතු මුහුද (ඉන්දියානු සාගරය) සම්බන්ධ කරමින් ඊජිප්තුව හරහා කපා ඇති කෘත්‍රිම නාවික ඇළ මාර්ගය කුමක්ද?",
        "සූවස් ඇළ (Suez Canal)", "පැනමා ඇළ", "කීල් ඇළ", "කොරින්ත් ඇළ",
        "1869 දී විවෘත කළ සූවස් ඇළ නිසා යුරෝපය හා ආසියාව අතර නැව්වලට අප්‍රිකාවේ සුබපැතුම් තුඩුව වටා යාම අවශ්‍ය නොවේ."),
      q(t, "අත්ලාන්තික් සාගරය (කැරිබියන් මුහුද) සහ පැසිෆික් සාගරය යා කරමින් මධ්‍යම ඇමෙරිකාවේ ඉදිකර ඇති අගුළු පද්ධති (Locks) සහිත ඇළ මාර්ගය කුමක්ද?",
        "පැනමා ඇළ (Panama Canal)", "සූවස් ඇළ", "බොස්පරස් සමුද්‍ර සන්ධිය", "බේරින් සමුද්‍ර සන්ධිය",
        "ගැටුන් විල (Gatun Lake) හරහා නැව් මීටර් 26 ක් ඉහළට ඔසවා නැවත පහළට බැස්සවීම මෙහි ඉංජිනේරු විශේෂත්වයයි."),
      q(t, "මැලේ අර්ධද්වීපය සහ ඉන්දුනීසියාවේ සුමාත්‍රා දූපත අතර පිහිටි ඉන්දියානු සාගරය හා දකුණු චීන මුහුද යා කරන ලොව කාර්යබහුලම සමුද්‍ර සන්ධිය කුමක්ද?",
        "මලක්කා සමුද්‍ර සන්ධිය (Strait of Malacca)", "හෝමුස් සමුද්‍ර සන්ධිය", "පෝක් සමුද්‍ර සන්ධිය", "ඩෝවර් සමුද්‍ර සන්ධිය",
        "මැදපෙරදිග සිට චීනය, ජපානය හා දකුණු කොරියාවට යන තෙල් හා වෙළඳ නැව්වලින් විශාල ප්‍රමාණයක් මෙම පටු මාර්ගයෙන් ගමන් කරයි."),
      q(t, "පර්සියානු බොක්ක හා ඕමාන් බොක්ක (අරාබි මුහුද) යා කරමින් ලෝකයේ මුහුදු මාර්ගයෙන් ගෙන යන ඛනිජ තෙල්වලින් පහෙන් එකක් පමණ ගමන් කරන සමුද්‍ර සන්ධිය කුමක්ද?",
        "හෝමුස් සමුද්‍ර සන්ධිය (Strait of Hormuz)", "ජිබ්‍රෝල්ටාර් සමුද්‍ර සන්ධිය", "මැගලන් සමුද්‍ර සන්ධිය", "ටොරස් සමුද්‍ර සන්ධිය",
        "ඉරානය හා ඕමානය/එක්සත් අරාබි එමීර් රාජ්‍යය අතර පිහිටි මෙය ලෝක බලශක්ති ආරක්ෂාවේ තීරණාත්මක සන්ධිස්ථානයකි."),
      q(t, "ශ්‍රී ලංකාව සහ ඉන්දියාව (තමිල්නාඩුව) වෙන් කරන පටු සමුද්‍ර තීරය හා මුහුදු බොක්ක කුමක්ද?",
        "පෝක් සමුද්‍ර සන්ධිය (Palk Strait) සහ මන්නාරම් බොක්ක (Gulf of Mannar)", "හෝමුස් සමුද්‍ර සන්ධිය හා බෙංගාල බොක්ක", "සුන්ඩා සමුද්‍ර සන්ධිය හා ජාවා මුහුද", "බේරින් සමුද්‍ර සන්ධිය",
        "මෙම නොගැඹුරු මුහුදු කලාපයේ රාම සේතු (ආදම්ගේ පාලම) හුණුගල් දූපත් දාමය පිහිටා ඇත."),
      q(t, "ආසියාව සහ උතුරු ඇමෙරිකාව (රුසියාව සහ ඇලස්කාව) වෙන් කරමින් ජාත්‍යන්තර දින රේඛාව ආසන්නයේ පිහිටි සමුද්‍ර සන්ධිය කුමක්ද?",
        "බේරින් සමුද්‍ර සන්ධිය (Bering Strait)", "ජිබ්‍රෝල්ටාර් සමුද්‍ර සන්ධිය", "බොස්පරස් සමුද්‍ර සන්ධිය", "කුක් සමුද්‍ර සන්ධිය",
        "අයිස් යුගයේදී මුහුදු මට්ටම පහළ බැස තිබූ විට 'බෙරින්ජියා' ගොඩබිම් පාලම ඔස්සේ මානවයන් ආසියාවේ සිට ඇමෙරිකාවට සංක්‍රමණය වූ බව සැලකේ."),
      q(t, "යුරෝපය (ස්පාඤ්ඤය) සහ අප්‍රිකාව (මොරොක්කෝව) වෙන් කරමින් මධ්‍යධරණී මුහුද හා අත්ලාන්තික් සාගරය යා කරන සමුද්‍ර සන්ධිය කුමක්ද?",
        "ජිබ්‍රෝල්ටාර් සමුද්‍ර සන්ධිය (Strait of Gibraltar)", "මලක්කා සමුද්‍ර සන්ධිය", "ඩේවිස් සමුද්‍ර සන්ධිය", "හඩ්සන් සමුද්‍ර සන්ධිය",
        "එහි පටුම ස්ථානය කිලෝමීටර 14 ක් පමණක් පළල වන අතර යුරෝපයේ සිට අප්‍රිකානු වෙරළ දැකගත හැකිය."),
      q(t, "'දකුණු ආසියානු කලාපීය සහයෝගිතා සංවිධානය' (SAARC) හි සාමාජික රටවල් අට මොනවාද?",
        "ශ්‍රී ලංකාව, ඉන්දියාව, පකිස්තානය, බංග්ලාදේශය, නේපාලය, භූතානය, මාලදිවයින සහ ඇෆ්ගනිස්ථානය", "චීනය, ජපානය, කොරියාව, වියට්නාමය, තායිලන්තය, ලංකාව, ඉන්දියාව, මැලේසියාව", "ඉන්දියාව, ඉරානය, ඉරාකය, සවුදි අරාබිය, ඕමානය, කටාර්, ලංකාව, නේපාලය", "ඕස්ට්‍රේලියාව, නවසීලන්තය, ඉන්දුනීසියාව, පිලිපීනය, සිංගප්පූරුව, භූතානය, බංග්ලාදේශය, නේපාලය",
        "SAARC සංවිධානයේ මූලස්ථානය නේපාලයේ කත්මණ්ඩු නුවර පිහිටා ඇති අතර 1985 දී ආරම්භ විය."),
      q(t, "'අග්නිදිග ආසියානු ජාතීන්ගේ සංගමය' (ASEAN) හි රටවල් 10 අතර ප්‍රධාන සාමාජික රටවල් කිහිපයක් මොනවාද?",
        "ඉන්දුනීසියාව, මැලේසියාව, සිංගප්පූරුව, තායිලන්තය, වියට්නාමය, පිලිපීනය, බෲනායි, කාම්බෝජය, ලාවෝසය සහ මියන්මාරය", "ජපානය, චීනය හා දකුණු කොරියාව", "ඉන්දියාව, ශ්‍රී ලංකාව හා නේපාලය", "ඊජිප්තුව, කෙන්යාව හා නයිජීරියාව",
        "ASEAN කලාපය වේගවත් ආර්ථික වර්ධනයක් හා ශක්තිමත් නිෂ්පාදන සැපයුම් ජාලයක් හිමි කලාපයකි."),
      q(t, "ඉන්දුනීසියාව ලොව වැඩිම දූපත් සංඛ්‍යාවක් (දූපත් 17,000+) ඇති 'දූපත් සමූහ රාජ්‍යයක්' (Archipelago) වන අතර එහි වැඩිම ජනගහනයක් ජීවත් වන දූපත කුමක්ද?",
        "ජාවා දූපත (Java - ජකර්තා අගනුවර පිහිටි)", "බෝර්නියෝ දූපත", "නව ගිනියා දූපත", "බාලි දූපත",
        "අධික ජනගහන තදබදය හා ජකර්තා නගරය මුහුදේ ගිලීමේ අවදානම නිසා ඉන්දුනීසියාව බෝර්නියෝ දූපතේ 'නුසන්තාරා' (Nusantara) නමින් නව අගනුවරක් ගොඩනඟමින් සිටී."),
      q(t, "'උතුරු ඇමෙරිකාවේ මහා විල් පහ' (Great Lakes - Superior, Michigan, Huron, Erie, Ontario) පිහිටා ඇත්තේ කුමන රටවල් දෙකෙහි දේශසීමාව ආශ්‍රිතවද?",
        "කැනඩාව සහ ඇමෙරිකා එක්සත් ජනපදය", "මෙක්සිකෝව සහ ඇමෙරිකාව", "බ්‍රසීලය සහ ආජන්ටිනාව", "රුසියාව සහ චීනය",
        "මිචිගන් විල සම්පූර්ණයෙන්ම ඇමෙරිකාව තුළ පිහිටා ඇති අතර අනෙක් විල් හතර කැනඩා-ඇමෙරිකා දේශසීමාවේ පිහිටයි."),
      q(t, "දකුණු ඇමෙරිකාවේ බොලිවියාව සහ පේරු දේශසීමාවේ ඇන්ඩීස් කඳුකරයේ මීටර් 3,812 ක් උසින් පිහිටි ලොව උසම නාවික ගමනාගමනය කළ හැකි විල කුමක්ද?",
        "ටිටිකාකා විල (Lake Titicaca)", "මරකයිබෝ විල", "මළ මුහුද", "නියසා විල",
        "මෙම විල මත 'උරොස්' (Uros) ජනතාව පන් ගස්වලින් සෑදූ පාවෙන දූපත්වල ජීවත් වීම සුවිශේෂී භූගෝලීය සංස්කෘතියකි."),
      q(t, "නැගෙනහිර අප්‍රිකාවේ කිලිමන්ජාරෝ, කෙන්යා ගිනි කඳු සහ ටැන්ගානිකා, මලාවි, තුර්කානා වැනි ගැඹුරු විල් නිර්මාණය වීමට මුල් වූ භූගෝලීය ව්‍යුහය කුමක්ද?",
        "නැගෙනහිර අප්‍රිකානු විවර නිම්නය (East African Rift Valley)", "සහරා කාන්තාර වැලි කඳු", "කොංගෝ ගංගා ඩෙල්ටාව", "ඇට්ලස් කඳු නැමිය",
        "අප්‍රිකානු තැටිය නූබියන් හා සෝමාලි තැටි ලෙස දෙකඩ වෙමින් පවතින මෙම කලාපය මානව පරිණාමයේ තොටිල්ල ලෙසද සැලකේ."),
      q(t, "පෘථිවියේ භූමි පෘෂ්ඨයේ ඇති පහත්ම ස්ථානය (මුහුදු මට්ටමේ සිට මීටර් 430 ක් පමණ පහළින්) සහ අධික ලවණතාව නිසා මිනිසුන්ට පහසුවෙන් පාවිය හැකි ජලාශය කුමක්ද?",
        "මළ මුහුද (Dead Sea - ජෝර්දානය හා ඊශ්‍රායලය අතර)", "රතු මුහුද", "කළු මුහුද", "බෝල්ටික් මුහුද",
        "ජෝර්දාන් ගංගාවෙන් ජලය ගලා ආවද පිටවීමක් නොමැති නිසා අධික වාෂ්පීභවනයෙන් ලවණතාව ~34% ක් දක්වා ඉහළ ගොස් ඇත."),
      q(t, "භූගෝලීය වශයෙන් 'මැදපෙරදිග' (Middle East / බටහිර ආසියාව) කලාපයේ ප්‍රධාන භූ-ආර්ථික හා භෞතික ලක්ෂණ මොනවාද?",
        "පුළුල් ශුෂ්ක කාන්තාර (අරාබි කාන්තාරය), යුප්‍රටීස්-ටයිග්‍රීස් ගංගා නිම්න, ලෝකයේ විශාලතම ඛනිජ තෙල් හා ස්වාභාවික වායු සංචිත සහ මහාද්වීප තුනක (ආසියා, අප්‍රිකා, යුරෝපා) සන්ධිස්ථානය වීම", "සදාහරිත වැසි වනාන්තරවලින් වැසී තිබීම", "වසර පුරා අධික හිම පතනය", "මුහුදු ප්‍රවේශයක් නොමැති වීම",
        "ජල හිඟය පියවා ගැනීමට සවුදි අරාබිය හා එක්සත් අරාබි එමීර් රාජ්‍යය මුහුදු ජලය ලවණහරණය (Desalination) බහුලව භාවිත කරයි."),
      q(t, "'නොර්ඩික් රටවල්' (Nordic Countries - නෝර්වේ, ස්වීඩනය, ෆින්ලන්තය, ඩෙන්මාර්කය, අයිස්ලන්තය) යුරෝපයේ කුමන කලාපයට අයත් වේද?",
        "උතුරු යුරෝපය (ස්කැන්ඩිනේවියානු හා උතුරු අත්ලාන්තික් කලාපය)", "මධ්‍යධරණී කලාපය", "බෝල්කන් කලාපය", "අයිබීරියානු අර්ධද්වීපය",
        "උතුරු අත්ලාන්තික් උණුසුම් දියවැල නිසා සමාන අක්ෂාංශවල ඇති කැනඩාවට හෝ සයිබීරියාවට වඩා නෝර්වේ වෙරළ තීරය ශීත ඍතුවේදී අයිස්වලින් තොරව පවතී."),
      q(t, "'අයිබීරියානු අර්ධද්වීපය' (Iberian Peninsula) තුළ පිහිටා ඇති නිරිතදිග යුරෝපීය රටවල් දෙක මොනවාද?",
        "ස්පාඤ්ඤය සහ පෘතුගාලය (සහ කුඩා ඇන්ඩෝරා/ජිබ්‍රෝල්ටාර්)", "ඉතාලිය සහ ග්‍රීසිය", "ප්‍රංශය සහ බෙල්ජියම", "පෝලන්තය සහ හංගේරියාව",
        "පිරෙනීස් කඳු වැටිය අයිබීරියානු අර්ධද්වීපය ප්‍රංශයෙන් වෙන් කරයි."),
      q(t, "'බෙනෙලක්ස් රටවල්' (Benelux) ලෙස හැඳින්වෙන බටහිර යුරෝපයේ ඉතා ජනාකීර්ණ හා වෙළඳ කේන්ද්‍රීය රටවල් තුන කුමක්ද?",
        "බෙල්ජියම (Belgium), නෙදර්ලන්තය (Netherlands) සහ ලක්සම්බර්ග් (Luxembourg)", "බ්‍රිතාන්‍යය, නෝර්වේ සහ ලැට්වියාව", "බල්ගේරියාව, නේපාලය සහ ලිතුවේනියාව", "බ්‍රසීලය, නයිජීරියාව සහ ලිබියාව",
        "නෙදර්ලන්තයේ රොටර්ඩෑම් යුරෝපයේ විශාලතම වරාය වන අතර බෙල්ජියමේ බ්‍රසල්ස් යුරෝපා සංගමයේ ප්‍රධාන මූලස්ථානයයි."),
      q(t, "ආක්ටික් හා ඇන්ටාක්ටික් කලාප අතර ඇති මූලික භෞතික භූගෝලීය වෙනස කුමක්ද?",
        "ආක්ටික් කලාපය යනු මහාද්වීපවලින් වට වූ මිදුණු සාගරයක් (Arctic Ocean) වන අතර ඇන්ටාක්ටිකාව යනු සාගරවලින් වට වූ ඝන අයිස් තට්ටුවකින් වැසුණු මහාද්වීපයකි", "දෙකම මහාද්වීප වේ", "දෙකම ගොඩබිම් නැති සාගර වේ", "ඇන්ටාක්ටිකාවේ ධ්‍රැව වලසුන් ජීවත් වේ",
        "ධ්‍රැව වලසුන් ආක්ටික් (උතුරේ) කලාපයේත් පෙන්ගුවින් පක්ෂීන් දක්ෂිණ අර්ධගෝලයේ (ඇන්ටාක්ටිකාව) හා ඒ අවටත් ජීවත් වෙති."),
      q(t, "'ඇන්ටාක්ටික් ගිවිසුම' (Antarctic Treaty System - 1959) මගින් ඇන්ටාක්ටිකා මහාද්වීපය වෙන් කර ඇත්තේ කුමන කටයුතු සඳහාද?",
        "සාමකාමී විද්‍යාත්මක පර්යේෂණ හා පරිසර සංරක්ෂණය සඳහා පමණක් වන අතර යුද කඳවුරු, න්‍යෂ්ටික අත්හදා බැලීම් හා ඛනිජ කැණීම් තහනම් කර ඇත", "කාර්මික නගර ඉදිකිරීමට", "වී වගාව සඳහා", "ගල් අඟුරු පතල් සඳහා",
        "වර්තමානයේ ලෝකයේ මිරිදිය අයිස්වලින් ~90% ක් පමණ ඇන්ටාක්ටිකා අයිස් තට්ටුවේ රැඳී ඇත."),
      q(t, "ඕස්ට්‍රේලියාවේ ඊසානදිග වෙරළට ඔබ්බෙන් පිහිටි කිලෝමීටර 2,300 කට වඩා දිග ලොව විශාලතම ජෛව නිර්මාණය හෙවත් කොරල් පර පද්ධතිය කුමක්ද?",
        "මහා බාධක පරය (Great Barrier Reef)", "බාර් රීෆ් (Bar Reef)", "බෙලීස් බාධක පරය", "හික්කඩුව කොරල් පරය",
        "සාගර උණුසුම් වීම හේතුවෙන් ඇතිවන 'කොරල් විරංජනය' (Coral Bleaching) මහා බාධක පරයට දැඩි තර්ජනයක් එල්ල කර ඇත."),
      q(t, "'මෙලනීසියාව, මයික්‍රොනීසියාව සහ පොලිනීසියාව' යන සංස්කෘතික-භූගෝලීය උප කලාප තුන අයත් වන්නේ කුමන මහාද්වීපික කලාපයටද?",
